/// Given any `n: i8`, returns an `(offset, category)`
/// such that
///   0 ≤ offset ≤ 2,
///   category ∈ {'A','B'},
/// and if we set
///   new_r = (n + offset).rem_euclid(4),
/// then
///   new_r == 1  ⇐⇒  category == 'A',
///   new_r == 3  ⇐⇒  category == 'B'.
#[requires(true)]
#[ensures(0 <= result.0 && result.0 <= 2)]
#[ensures(result.1 == 'A' || result.1 == 'B')]
#[ensures(((n + result.0).rem_euclid(4) == 1) <==> (result.1 == 'A'))]
#[ensures(((n + result.0).rem_euclid(4) == 3) <==> (result.1 == 'B'))]
fn solve(n: i8) -> (i8, char) {
    // Compute a non-negative remainder in 0..=3
    match n.rem_euclid(4) {
        1 => (0, 'A'), // n % 4 == 1 → already category A
        2 => (1, 'B'), // n % 4 == 2 → shift by +1 to get remainder 3 → category B
        3 => (2, 'A'), // n % 4 == 3 → shift by +2 to get remainder 1 → category A
        0 => (1, 'A'), // n % 4 == 0 → shift by +1 to get remainder 1 → category A
        _ => unreachable!(), // rem_euclid(4) is always in 0..=3
    }
}

